import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Build, deployment and quality audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/BUILD-DEPLOYMENT-AND-QUALITY.html"}],["meta",{"property":"og:title","content":"Build, deployment and quality audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/BUILD-DEPLOYMENT-AND-QUALITY.html"}],["meta",{"name":"twitter:title","content":"Build, deployment and quality audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/BUILD-DEPLOYMENT-AND-QUALITY.md","filePath":"audits/BUILD-DEPLOYMENT-AND-QUALITY.md","lastUpdated":1794184492000}`),a={name:`audits/BUILD-DEPLOYMENT-AND-QUALITY.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="build-deployment-and-quality-audit" tabindex="-1">Build, deployment and quality audit <a class="header-anchor" href="#build-deployment-and-quality-audit" aria-label="Permalink to “Build, deployment and quality audit”">​</a></h1><h2 id="deploy-01-—-the-dev-preview-and-production-share-one-github-pages-deployment" tabindex="-1">DEPLOY-01 — The dev preview and production share one GitHub Pages deployment <a class="header-anchor" href="#deploy-01-—-the-dev-preview-and-production-share-one-github-pages-deployment" aria-label="Permalink to “DEPLOY-01 — The dev preview and production share one GitHub Pages deployment”">​</a></h2><p><strong>Severity: P2</strong></p><p><strong>Evidence:</strong> GitHub Pages project hosting publishes one site tree at the project root. The new dev workflow publishes a separate branch <code>dev_pages-preview-artifact</code>, and the dev version of <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/.github/workflows/pages.yml" target="_blank" rel="noreferrer">pages.yml</a> assembles that tree under <code>site/dev/</code> alongside the production web/docs artifact branches.</p><p><strong>Impact:</strong> the path is isolated in the deployed file tree, but it is not a separate Pages environment or independent deployment target. A dev deployment re-deploys the complete assembled site. More importantly, the current <strong>main</strong> version of <code>pages.yml</code> does not include the dev artifact. After the preview-aware workflow deploys, a later production deployment using the old main assembler can remove <code>/dev/</code>.</p><p><strong>Recommendation:</strong></p><ol><li>Keep the dev artifact/state branches separate and prefixed <code>dev_</code>.</li><li>Preserve the shared Pages deployment concurrency group to avoid production/dev deploy races.</li><li>Merge the preview-aware assembler to main before relying on the preview path long-term, or move preview hosting to a genuinely separate host/environment.</li><li>Add a deployment contract test proving that a main deployment includes the current dev preview artifact when one exists and leaves the production root component SHAs unchanged.</li><li>Verify that the dev artifact contains root-level preview files before extracting it into <code>site/dev/</code>.</li></ol><h2 id="build-pipeline-assessment" tabindex="-1">Build pipeline assessment <a class="header-anchor" href="#build-pipeline-assessment" aria-label="Permalink to “Build pipeline assessment”">​</a></h2><h3 id="strengths" tabindex="-1">Strengths <a class="header-anchor" href="#strengths" aria-label="Permalink to “Strengths”">​</a></h3><ul><li>Web and documentation are produced as separate artifacts, which avoids making a web-only change wait for the documentation benchmark pipeline.</li><li>The docs workflow generates benchmark data, validates expected scenario counts/parameter sweeps and then builds the docs component.</li><li>The Pages assembler composes independently published web/docs artifacts and tracks their SHAs to avoid redundant deployments.</li><li>The dev workflow uses <code>FD_CAL_PREVIEW=true</code>, a dedicated <code>dev_pages-preview-artifact</code> branch, noindex metadata and a visible preview banner.</li><li>The preview output is path-prefixed so relative web assets and docs base URLs resolve under <code>/FD-Calculator/dev/</code>.</li><li>The preview workflow uses short-lived Actions artifacts named <code>dev-web-site</code> and <code>dev-docs-site</code>; persistent Git branches are prefixed <code>dev_</code>.</li></ul><h3 id="verification-still-required" tabindex="-1">Verification still required <a class="header-anchor" href="#verification-still-required" aria-label="Permalink to “Verification still required”">​</a></h3><p>The dev-preview build/deploy run for the audited source revision is still in progress (<a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42509949422" target="_blank" rel="noreferrer">run 42509949422</a>). Earlier attempts exposed three pipeline defects that have been corrected on <code>dev</code>: preview metadata was not injected because of shell-variable escaping; the workflow expressions were escaped incorrectly; and the artifact upload searched a runner-temp path that was not found, so build outputs now live under the workspace. Do not call the preview live until the current run publishes <code>dev_pages-preview-artifact</code> and the Pages deployment succeeds.</p><p>After deployment, verify these paths:</p><ul><li><code>/FD-Calculator/dev/</code></li><li><code>/FD-Calculator/dev/web/</code></li><li><code>/FD-Calculator/dev/docs/</code></li></ul><p>Check that each page uses noindex metadata, all relative assets/data/worker requests stay under the dev path, the app displays the dev banner, and the production root still serves the main artifacts.</p><h2 id="qa-01-—-the-automated-suite-is-strong-on-node-contracts-but-lacks-browser-level-coverage" tabindex="-1">QA-01 — The automated suite is strong on Node contracts but lacks browser-level coverage <a class="header-anchor" href="#qa-01-—-the-automated-suite-is-strong-on-node-contracts-but-lacks-browser-level-coverage" aria-label="Permalink to “QA-01 — The automated suite is strong on Node contracts but lacks browser-level coverage”">​</a></h2><p><strong>Evidence:</strong> the repository contains tests for configuration, dates/foundations, cash-flow components, account provenance, runtime/ledger, strategy parity, search, worker contracts, report output, motion guidelines and Pages workflow contracts. The workflow runs <code>npm test</code>, syntax checks and static build checks.</p><p><strong>Gap:</strong> no Playwright/Cypress/WebDriver browser suite or screenshot/visual-regression runner was identified. Static source assertions do not verify rendered layout, keyboard focus order, screen-reader announcements, chart rendering, file import/export or actual GitHub Pages subpath behaviour.</p><p><strong>Recommendation:</strong> add a small browser smoke suite for:</p><ul><li>Load catalogue and render initial form.</li><li>Import/export valid and malicious JSON.</li><li>Run one deterministic simulation and download/open the standalone report.</li><li>Check no console errors and no failed same-origin requests.</li><li>Exercise 320px/mobile and desktop layouts.</li><li>Verify keyboard-only operation, validation error announcements and reduced motion.</li><li>Open the dev preview at the deployed subpath to catch base-path and worker/data URL regressions.</li></ul><h2 id="ci-and-release-quality" tabindex="-1">CI and release quality <a class="header-anchor" href="#ci-and-release-quality" aria-label="Permalink to “CI and release quality”">​</a></h2><ul><li>The Node test workflow was successful at the immediately preceding dev source revision <code>2781bd3</code>; the audited revision <code>358fbef</code> changed only workflow expression escaping and requires its own run result.</li><li>No manual browser QA, Lighthouse run, WCAG audit, CSP/header scan or external dependency/security scan was completed during this source review.</li><li><code>npm ci</code> reports no installed dependencies beyond the project itself; VitePress is installed separately by the documentation build script without updating the lockfile. This is reproducible only to the extent that the VitePress version is pinned by the script.</li><li>Action references use version tags rather than immutable commit SHAs. Consider SHA pinning for higher supply-chain assurance, with automated update tooling.</li><li>Benchmark validation checks expected observation counts and parameter sweeps; it does not independently validate every bank-rate source or the financial correctness of each observation.</li></ul><h2 id="operational-recommendations" tabindex="-1">Operational recommendations <a class="header-anchor" href="#operational-recommendations" aria-label="Permalink to “Operational recommendations”">​</a></h2><ol><li>Keep the preview and production deployments serialized.</li><li>Preserve the previous successful production artifact if a component build fails.</li><li>Keep preview pages out of production sitemaps and set noindex on every preview HTML entry point.</li><li>Add a smoke test for generated URLs and worker/module loading under the project subpath.</li><li>Merge the preview-aware Pages assembler to main before treating /dev as durable.</li><li>Add a concise deployment runbook documenting how to inspect/roll back web, docs and dev artifact refs.</li></ol>`,24)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};